    private static LookupField YesNo(string key, string column, string label, bool required = false) =>
        new(key, column, label, 1, Required: required, Kind: LookupFieldKind.Choice, Choices: ["Y", "N"], ChoiceLabels: ["Yes", "No"]);

    private static LookupField SuppLimit(string key, string column, string label) =>
        new(key, column, label, 1, Kind: LookupFieldKind.Choice, Choices: ["A", "B", "C"], ChoiceLabels: ["Share limit for family", "Share limit for supplementary", "Separate limit for supplementary"]);

    private static LookupField Code(string key, string column, string label, int maxLength, LookupSource source, bool required = false, bool isKey = false) =>
        new(key, column, label, maxLength, Required: required, IsKey: isKey, Kind: LookupFieldKind.Choice, Source: source);

